const ui={role:"surveyor",grade:"G2",mState:"Gap",mSearch:"",drawerCrit:null,critNavList:[],critNavLocked:false,drawerAct:null,drawerFromList:false,pendingSigned:null,critScope:"all",selectMode:false,selCrit:new Set(),bulkStatus:"Evidenced",bulkCode:"O",bulkAct:null,evSeg:"inbox",evSearch:"",evEditId:null,pickerSearch:"",pickerFor:null,captureBatch:[],captureLinks:{},batchStatus:"Evidenced",batchCode:"O",formsSearch:"",formsAct:null,preflightAct:null,planOpen:false,preview:null,modal:null,pendingBackup:null,pendingReturn:null,fillTpl:null,toast:"",toastUndo:false};
